/* Hungarian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Istvan": "crowned — Greek Stephanos", "Katalin": "pure — Greek katharos", "Janos": "God is gracious — Hebrew Yohanan", "Erzsebet": "God is my oath — Hebrew Elisheva", "Laszlo": "glorious ruler — Slavic Vladislav", "Maria": "A beloved feminine name.", "Nagy": "The most common Hungarian surname.", "Kovacs": "A very common surname.", "Toth": "A widespread surname.", "Szabo": "A classic craft surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Istvan';
console.log(lookup(q));

